export const meta = {
  name: 'bug-rate-root-cause',
  description: 'Diagnose why the lobu repo has a high defect rate and produce a prioritized remediation plan',
  phases: [
    { title: 'Investigate', detail: '10 parallel investigators across defect surfaces' },
    { title: 'Verify', detail: 'adversarially refute each proposed root cause' },
    { title: 'Synthesize', detail: 'rank surviving causes into a remediation plan' },
  ],
}

const REPO = '/Users/burakemre/Code/lobu'

const COMMON = `You are investigating the git repository at ${REPO} (a Bun/TypeScript monorepo called "lobu").

CONTEXT — measured facts about this repo over the last 8 weeks:
- 907 commits total: 335 "fix" commits vs 231 "feat" commits (1.45 fixes per feature)
- Fix-commit bodies mention "regress" 71 times, "broke" 35 times, "again" 136 times
- 884 test files vs 1088 source files
- Fix commits by scope: server=56, slack=15, gateway=15, connections=12, mcp=10, oauth=9, behaviors=9, cli=8, authz=8
- Files most often touched by FIX commits: ${JSON.stringify(args.topFixFiles, null, 1)}

THE QUESTION: Why is this codebase producing so many bugs, and what specific structural change would most reduce the rate?

RULES:
- Ground EVERY claim in a file path, commit SHA, PR number, or command output. No speculation presented as fact.
- Read AGENTS.md and docs/GOTCHAS.md early — they encode the team's own hard-won rules; a rule that exists but is repeatedly violated is itself a finding.
- Use READ-ONLY git/gh/grep commands only. NEVER commit, push, checkout, switch branches, stash, or modify ANY file. Do not run 'make' targets that build or write.
- Prefer 'git log', 'git show', 'gh pr view', 'gh pr list', grep, and reading files.
- Distinguish "many fixes" from "many bugs" — a team that finds and fixes its own bugs pre-merge is healthy. Look for evidence of bugs that reached MAIN or PROD and had to be fixed after.
- Be specific and concrete. "Add more tests" is a useless finding. "Function X in file Y has 6 callers that each re-derive the org scope, and 4 fix commits all patched one caller at a time" is a useful finding.`

const FINDING_SCHEMA = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'rootCause', 'evidence', 'proposedFix', 'estimatedBugsExplained', 'confidence'],
        properties: {
          title: { type: 'string', description: 'Short name for this root cause' },
          rootCause: { type: 'string', description: 'The structural/process reason bugs keep appearing here' },
          evidence: { type: 'string', description: 'Concrete file paths, commit SHAs, PR numbers, command output backing this' },
          proposedFix: { type: 'string', description: 'Specific actionable change — a guard, a refactor, a CI gate, a process change' },
          estimatedBugsExplained: { type: 'number', description: 'How many of the 335 fix commits this root cause plausibly accounts for' },
          confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
        },
      },
    },
  },
}

const INVESTIGATORS = [
  {
    key: 'repeat-fix-files',
    prompt: `Focus: THE REPEAT-FIX HOTSPOTS. Take the top repeat-fix files listed above. For the top 5, run 'git log --oneline -S" " --follow <file>' and 'git log --oneline <file>' to get their fix history, then 'git show' several of those fix commits. Determine: are these files being fixed repeatedly for the SAME underlying reason (a shared structural flaw) or unrelated reasons (just a busy file)? Read the actual files. Look for god-objects, missing abstractions, copy-pasted scope/authz/filter logic across many call sites, or an interface everyone gets wrong. Quantify how many distinct fixes share a root cause.`,
  },
  {
    key: 'regressions',
    prompt: `Focus: REGRESSIONS — bugs that reappear. Search fix commits whose message or body mentions regress/broke/again/reintroduced/missed-in/follow-up. Use: git log --since="12 weeks ago" --grep="regress" --grep="broke" --grep="again" -i --pretty=fuller. For 10-15 of these, 'git show' them and identify what the PREVIOUS change was that broke it (git log -S on the touched lines, or git blame). Build a concrete list of regression PAIRS: "PR A broke what PR B fixed". Then answer: what class of change causes regressions here, and was there a test that should have caught it?`,
  },
  {
    key: 'test-efficacy',
    prompt: `Focus: TEST SUITE EFFECTIVENESS. There are 884 test files for 1088 source files — a high ratio, yet the bug rate is high. That is the paradox to explain. Investigate: (1) For 10 recent fix commits, did the fix ADD a test? Use 'git show --stat'. (2) What do the tests actually assert — are they mock-heavy tests that assert the mock rather than behavior? Read several test files in packages/server/src/__tests__. (3) Are integration tests (real DB) rare vs unit tests with mocks? (4) Check the memory-noted trap: does the suite mock the assumed error shape rather than the production one? (5) Read Makefile test targets and .github/workflows/ci.yml — what actually runs on every PR vs what is skipped or optional?`,
  },
  {
    key: 'ci-gates',
    prompt: `Focus: CI AND MERGE GATES. Read every file in .github/workflows/ and the Makefile (targets: pre-pr, review, review-fix, typecheck, test-unit, test-integration). Determine precisely: what is a REQUIRED check to merge vs advisory? Is test-integration run on PRs or only manually? Is there a path where a PR merges with only a typecheck? Then check reality: use 'gh pr list --state merged --limit 60 --json number,mergedAt,statusCheckRollup' and look for PRs merged with failing/skipped/pending checks, and for --admin merges. AGENTS.md says never --admin past a check that has not reported — find violations. Quantify the gap between the documented gate sequence and what actually happens.`,
  },
  {
    key: 'pr-size-review',
    prompt: `Focus: PR SIZE AND REVIEW DEPTH. Use 'gh pr list --state merged --limit 150 --json number,title,additions,deletions,changedFiles,reviews,comments,mergedAt'. Compute the distribution of PR size. Correlate: do LARGE PRs (>800 lines or >15 files) get FOLLOWED by fix commits touching the same files within days? Test that correlation concretely on at least 8 large PRs — for each, list the fix PRs that landed after it on the same files. Also measure review depth: how many merged PRs had ZERO human review comments? How fast were PRs merged after opening (gh pr view --json createdAt,mergedAt)? Is this effectively a solo-author repo with automated review only?`,
  },
  {
    key: 'server-package',
    prompt: `Focus: THE packages/server PACKAGE — it owns 56 of 335 fixes, far more than any other. Read packages/server/AGENTS.md if it exists. Map the package: how many files, what are the largest files, what are the main subsystems (gateway/, tools/admin/, worker-api/, lobu/, watchers/, sandbox/)? Find the architectural reason this package is defect-dense: is it a layering problem (business logic mixed with transport), a size problem, a fan-in problem (everything depends on it), or a boundary problem (it is where multi-tenant scope/authz decisions live)? Use grep to count how many distinct places re-implement org-scoping or authz filtering. Be concrete about which subsystem is worst.`,
  },
  {
    key: 'multitenant-scope',
    prompt: `Focus: MULTI-TENANCY AND SCOPE BUGS. Many fix titles involve org scoping, ACL gates, visibility predicates, and identity: e.g. "scope platform conversation reads to the ambient org too" (#2181), "scope threads to the ambient org" (#2176), "gate search_memory connections on the shared visibility predicate" (#2191), "surface pending approvals hidden by the ACL resource gate" (#2229), "stop leaking connection/feed config secrets on every read path" (#2195). Read those commits with 'git show'. Then grep the codebase for how org scope and visibility are applied to queries. THE KEY QUESTION: is org-scoping enforced by a single chokepoint, or must every query author remember to add it? If the latter, that is a systemic defect generator — quantify how many call sites must independently get it right, and propose the chokepoint design.`,
  },
  {
    key: 'security-fixes',
    prompt: `Focus: SECURITY AND CREDENTIAL DEFECTS. Recent fixes include "encrypt env auth-profile credentials at rest" (#2198), "stop leaking connection/feed config secrets on every read path" (#2195), "allowlist the agent environment and split the egress proxy credential" (#2263), "deny new-style nix CLI and ad-hoc package runners" (#2259), "bind the worker token's verified agent identity to the MCP session" (#2128). Read these commits. AGENTS.md states "Workers never receive real credentials" and "Text matcher is never the boundary". Determine: are these security fixes patching a DESIGN that keeps producing holes (e.g. deny-lists instead of allow-lists, string matching instead of structural enforcement, secrets flowing by default and being redacted after)? Find the pattern and the structural fix.`,
  },
  {
    key: 'vocab-migration',
    prompt: `Focus: INCOMPLETE MIGRATIONS AND RENAMES. There is a running watcher-to-Behavior rename: fixes include "canonicalize legacy watcher resourceKind on supersede" (#2114), "emit behavior, not watcher, in counts_by_kind" (#2113), "approval cards must emit resourceKind/attribution behavior not watcher" (#2105), "read renamed behavior_run_* columns" (#2041). Count how many fix commits are cleanup from an incomplete rename or migration. Grep for how many places still use 'watcher' vocabulary. Then generalize: does this team ship migrations in a way that leaves a long tail of one-at-a-time fixes (rename half, discover the rest in prod)? Look for other incomplete migrations too (schema column renames, API vocabulary, entity types). Propose how migrations should be gated so the tail does not exist.`,
  },
  {
    key: 'agent-authorship',
    prompt: `Focus: HOW THE CODE IS AUTHORED. This repo is developed heavily with AI coding agents (see AGENTS.md, .claude/ directory, 'make review', 'make review-fix', codex-auto-approve.yml). Investigate whether the AUTHORING PROCESS is a defect source. Read AGENTS.md and docs/GOTCHAS.md fully — they are a long list of rules written in response to past failures, which is itself evidence. Check: how many rules exist, and do fix commits show those rules being violated repeatedly anyway? Look at .github/workflows/claude.yml and codex-auto-approve.yml — is code being auto-approved and merged with weak human oversight? Examine commit authorship/timing patterns (git log --pretty='%an %ae %ad'). Assess honestly: is the bug rate a symptom of high-velocity agent authorship with review that catches style but not semantics? Be blunt and evidence-based, not flattering.`,
  },
]

phase('Investigate')

const investigated = await pipeline(
  INVESTIGATORS,
  inv => agent(`${COMMON}\n\n=== YOUR ASSIGNMENT ===\n${inv.prompt}\n\nReturn 2-5 findings. Quality over quantity — a single well-evidenced root cause beats five guesses.`,
    { label: `investigate:${inv.key}`, phase: 'Investigate', schema: FINDING_SCHEMA, effort: 'high' }),
  (res, inv) => {
    if (!res || !res.findings || !res.findings.length) return []
    return parallel(res.findings.map(f => () =>
      agent(`You are an adversarial verifier working in the git repo at ${REPO}. Your job is to REFUTE a claimed root cause for the repo's high bug rate. Default to "refuted" if the evidence does not hold up.

CLAIMED ROOT CAUSE: ${f.title}
REASONING: ${f.rootCause}
EVIDENCE OFFERED: ${f.evidence}
PROPOSED FIX: ${f.proposedFix}

Independently check the evidence with READ-ONLY commands (git log/show/blame, gh pr view, grep, reading files). NEVER modify, commit, checkout, or write anything.

Refute if ANY of these hold:
- The cited files/commits/PRs do not exist or do not say what is claimed
- The correlation is real but the causal story is wrong (e.g. a file is fixed often merely because it is large or frequently EXTENDED, not because it is defective)
- The claim confuses healthy pre-merge bug-finding with bugs escaping to production
- The proposed fix would not actually have prevented the cited bugs — walk through 2 of the specific cited bugs and check whether the fix stops them
- The claim is generic advice that would apply to any codebase and is not grounded in THIS repo

Verdict "supported" ONLY if you personally re-verified at least two concrete pieces of evidence and the causal chain holds.`,
      { label: `verify:${inv.key}`, phase: 'Verify', effort: 'high', schema: {
        type: 'object',
        required: ['refuted', 'reasoning', 'verifiedEvidence'],
        properties: {
          refuted: { type: 'boolean' },
          reasoning: { type: 'string' },
          verifiedEvidence: { type: 'string', description: 'What you personally re-ran or re-read, and what it showed' },
          correctedSeverity: { type: 'number', description: 'Your own estimate of fix commits this explains, after checking' },
        },
      } })
      .then(v => ({ ...f, source: inv.key, verdict: v }))
    ))
  }
)

const all = investigated.flat().filter(Boolean)
const survived = all.filter(f => f.verdict && !f.verdict.refuted)
const refuted = all.filter(f => f.verdict && f.verdict.refuted)

log(`${all.length} findings proposed, ${survived.length} survived adversarial verification, ${refuted.length} refuted`)

phase('Synthesize')

const synthesis = await agent(`You are the lead engineer writing the final diagnosis for the repo at ${REPO}.

The measured symptom: over 8 weeks, 335 fix commits vs 231 feat commits. 71 fix bodies mention regressions.

${survived.length} candidate root causes SURVIVED independent adversarial verification:
${JSON.stringify(survived.map(f => ({ title: f.title, rootCause: f.rootCause, evidence: f.evidence, fix: f.proposedFix, explains: f.verdict.correctedSeverity ?? f.estimatedBugsExplained, verifierNotes: f.verdict.verifiedEvidence })), null, 1)}

${refuted.length} were REFUTED and must NOT appear in your diagnosis as causes (listed only so you do not re-derive them):
${JSON.stringify(refuted.map(f => ({ title: f.title, whyRefuted: f.verdict.reasoning })), null, 1)}

Write the final answer as markdown. Requirements:
1. Open with a direct verdict: what is ACTUALLY driving the bug rate. Lead with the single biggest cause. If the honest answer is that the bug rate is partly healthy (fast shipping + good self-detection) say so plainly and separate "noise" from "real decay".
2. Merge overlapping findings from different investigators into single causes — do not repeat the same cause under three names.
3. Rank causes by how many of the 335 fix commits they explain. Give the number.
4. For each cause: the evidence (file paths / PR numbers / SHAs), and the specific structural fix.
5. End with a prioritized remediation plan: what to do first, second, third. Each item must be concrete enough to start on Monday — a named CI gate, a named refactor with the chokepoint file, a named process change. Include rough effort (hours/days) and which cause it kills.
6. Be blunt. The reader is the repo owner and wants the real diagnosis, not reassurance. Do not pad with generic engineering advice.`,
  { label: 'synthesize', phase: 'Synthesize', effort: 'max' })

return { synthesis, survivedCount: survived.length, refutedCount: refuted.length, survived, refuted }

