export const meta = {
  name: 'harden-verification-discipline',
  description: 'Turn this session\'s verification failures into enforceable repo guards and agent rules',
  phases: [
    { title: 'Investigate', detail: 'find whether each failure mode is systemic and mechanically detectable' },
    { title: 'Verify', detail: 'refute proposed guards that would not have caught the actual failure' },
    { title: 'Synthesize', detail: 'produce the concrete guard set + AGENTS.md deltas' },
  ],
}

const REPO = args.repo

const COMMON = `You are working in the git repo at ${REPO} (Bun/TypeScript monorepo, "lobu"). READ-ONLY: use git log/show/grep, gh, psql, reading files. NEVER commit, push, checkout, switch branches, stash, or modify ANY file.

CONTEXT — a real debugging session just produced these VERIFICATION failures (not code bugs — failures in how correctness was CHECKED):
${JSON.stringify(args.session_failures, null, 1)}

What DID work in that session:
${JSON.stringify(args.what_worked, null, 1)}

Read AGENTS.md and docs/GOTCHAS.md first — they already encode many hard-won rules, and two entries relevant here already exist (feedback_absence_needs_origin_main_grep, feedback_guards_must_assert_coverage). A rule that EXISTS but was still violated is itself the most important kind of finding.

THE GOAL: make these failure modes mechanically impossible or loudly detectable, rather than relying on an agent remembering a rule. Prefer, in order:
1. A CI check / test / lint rule that fails automatically
2. A repo script or helper that makes the correct thing the easy default
3. A tightly-worded AGENTS.md rule (weakest — only when 1 and 2 are impossible)

RULES:
- Ground every claim in a file path, command output, or commit SHA.
- Be brutally honest about what is NOT mechanizable. A rule nobody can enforce is worse than admitting the gap.
- "Be more careful" is a non-answer. Reject it.`

const SCHEMA = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'failureMode', 'mechanism', 'evidence', 'enforcementTier', 'wouldHaveCaught'],
        properties: {
          title: { type: 'string' },
