          evidence: { type: 'string', description: 'File paths, command output, or SHAs proving this is systemic and the guard is implementable here' },
          enforcementTier: { type: 'string', enum: ['ci-check', 'repo-script', 'agents-md-rule'] },
          wouldHaveCaught: { type: 'string', description: 'Walk through the SPECIFIC session failure and show this guard firing on it' },
          effortHours: { type: 'number' },
        },
      },
