}

const INVESTIGATORS = [
  {
    key: 'stale-tree',
    prompt: `Focus: THE STALE-TREE / ABSENCE-PROOF failure. An agent grepped the working tree, found nothing, and declared code nonexistent that was live on origin/main. AGENTS.md/memory already has a rule about this and it was STILL violated.
Investigate: (a) Why is the working tree stale here — is it worktrees, submodules, gitignored build output, or partial checkouts? Reproduce the condition if you can. (b) Is there a mechanical guard? Consider a repo script like 'scripts/absent.sh <pattern>' that greps BOTH the tree and 'git grep origin/main' and refuses to report absence unless both are empty. (c) Could a CI check or a git hook catch this class? Be concrete about what such a wrapper should do and where it should live. Check whether any similar helper already exists in scripts/.`,
  },
  {
    key: 'truncated-output',
    prompt: `Focus: THE TRUNCATED-QUERY failure — the highest-cost one. A psql query for unique indexes was piped through 'head -6', the second (decisive) index scrolled off, and a false positive was reported at 85 confidence and dispatched to an agent.
